\begin{tikzpicture}[font=\sffamily, scale=0.9, every node/.style={font=\sffamily}]
    % Bunsen burner and flame
    \draw[thick] (1.5,0) rectangle (2.5,0.4);
    \draw[thick] (1.8,0.4) -- (1.8,1.2);
    \draw[thick] (2.2,0.4) -- (2.2,1.2);
    \draw[thick, fill=gray!30] (2,1.2) ellipse (0.4 and 0.1);
    % Flame
    \draw[thick, orange, fill=orange!30] (2,1.3) .. controls (1.6,2.2) and (1.9,2.5) .. (2,3.0) .. controls (2.1,2.5) and (2.4,2.2) .. (2,1.3);
    \draw[thick, blue, fill=blue!20] (2,1.3) .. controls (1.8,1.8) and (1.9,2.0) .. (2,2.3) .. controls (2.1,2.0) and (2.2,1.8) .. (2,1.3);

    % Tripod and wire gauze
    \draw[thick] (0.5,2.6) -- (3.5,2.6); % wire gauze
    \draw[thick] (0.5,2.6) -- (0.2,0);   % left leg
    \draw[thick] (3.5,2.6) -- (3.8,0);   % right leg

    % Round bottomed flask
    \draw[thick] (2,2.7) circle (1.5);
    \node at (2,2.4) [below] {};

    % Sea water liquid inside flask (using dotregion helper or simple fill/lines)
    % We'll use a clipping region for the liquid
    \begin{scope}
        \clip (2,2.7) circle (1.48);
        \fill[gray!20] (0,0) rectangle (4,2.3);
        % Add some dots or waves to indicate liquid
        \foreach \x in {1.2, 1.6, 2.0, 2.4, 2.8}
            \foreach \y in {1.5, 1.8, 2.1}
                \node[circle,fill,inner sep=0.7pt,gray!60] at (\x+\y*0.1-0.2, \y) {};
    \end{scope}
    \draw[thick] (2,2.7) circle (1.5);

    % Flask neck and side arm
    \draw[thick] (1.6,4.0) -- (1.6,4.6);
    \draw[thick] (2.4,4.0) -- (2.4,4.6);

    % Side arm going right
    \draw[thick] (2.4,4.2) -- (6.0,2.6);
    \draw[thick] (2.3,3.9) -- (5.7,2.3);

    % Cork / Stopper
    \fill[white] (1.6,4.2) rectangle (2.4,4.6);
    \draw[thick, fill=gray!40] (1.6,4.2) rectangle (2.4,4.6);
    \draw[thick] (1.6,4.6) -- (2.4,4.6);
    \draw[thick] (1.6,4.2) -- (2.4,4.2);

    % Thermometer
    \draw[thick] (2,5.8) -- (2,3.9);
    \draw[thick] (2,5.8) circle (0.08);
    \draw[thick, fill=red] (2,4.2) circle (0.08); % bulb level with side arm
    \draw[thick] (1.9,4.4) -- (2.1,4.4);
    \draw[thick] (1.9,4.8) -- (2.1,4.8);
    \draw[thick] (1.9,5.2) -- (2.1,5.2);
    \draw[thick] (1.9,5.6) -- (2.1,5.6);

    % Liebig Condenser (X)
    % Outer jacket
    \draw[thick, fill=white] (4.0,3.3) rectangle (8.5,1.7);
    % Inner tube
    \draw[thick, fill=white] (3.8,2.7) -- (8.7,1.1) -- (8.7,1.4) -- (3.8,3.0) -- cycle;
    % Actually, let's align the inner tube with the side arm (from 6.0,2.6 to 8.7,1.5 approx)
    % Let's redraw the condenser cleanly as a slanted coaxial cylinder unit:

    % Clear area behind condenser
    \fill[white] (4.2,3.4) rectangle (8.6,0.6);

    % Condenser outer tube (jacket)
    \begin{scope}[rotate around={-25:(6.0,2.1)}]
        \draw[thick, fill=white] (4.2, 1.8) rectangle (8.2, 2.6);
        % Inner glass tube
        \draw[thick] (4.2, 2.2) -- (8.2, 2.2);

        % Water in / out nozzles
        \draw[thick] (4.6, 2.6) -- (4.6, 3.0);
        \draw[thick] (4.4, 2.6) -- (4.4, 3.0);
        \fill[white] (4.4,2.55) rectangle (4.6,2.65);

        \draw[thick] (7.8, 1.8) -- (7.8, 1.4);
        \draw[thick] (7.6, 1.8) -- (7.6, 1.4);
        \fill[white] (7.6,1.75) rectangle (7.8,1.85);
    \end{scope}

    % Connect side arm smoothly into condenser inner tube
    % Side arm ends around (5.85, 2.45)
    % Let's make the side arm straight into the condenser:
    \draw[thick] (2.4, 4.1) -- (5.2, 2.8);
    \draw[thick] (2.4, 3.9) -- (5.0, 2.6);

    % Redraw condenser precisely over the path
    \begin{scope}[shift={(5.1, 2.7)}, rotate=-25]
        % outer jacket
        \draw[thick, fill=white] (0, -0.4) rectangle (4.5, 0.4);
        % inner tube
        \draw[thick] (0, 0) -- (4.5, 0);
        % water connections
        \draw[thick] (0.5, 0.4) -- (0.5, 0.8);
        \draw[thick] (0.7, 0.4) -- (0.7, 0.8);

        \draw[thick] (3.8, -0.4) -- (3.8, -0.8);
        \draw[thick] (4.0, -0.4) -- (4.0, -0.8);
    \end{scope}

    % Outlet of condenser leading to conical flask
    \draw[thick] (8.7, 0.6) -- (9.2, 0.1);
    \draw[thick] (8.4, 0.4) -- (8.9, -0.1);

    % Conical flask
    \draw[thick] (8.8,-1.5) -- (9.8,-1.5) -- (9.4,-0.5) -- (9.1,-0.5) -- cycle;
    \draw[thick] (9.1,-0.5) -- (9.1,0.0) -- (9.4,0.0) -- (9.4,-0.5);
    \fill[white] (9.1,-0.5) rectangle (9.4,0.0);
    \draw[thick] (9.1,-0.5) -- (9.1,0.0);
    \draw[thick] (9.4,-0.5) -- (9.4,0.0);

    % Pure water liquid in conical flask
    \fill[gray!20] (9.0,-1.45) rectangle (9.6,-1.0);
    \draw[thick] (8.8,-1.5) -- (9.8,-1.5) -- (9.4,-0.5) -- (9.1,-0.5) -- cycle;
    % Drops
    \draw[thick, fill=blue!30] (9.25,-0.3) circle (0.05);

    % Labels and Leaders
    \node at (2, 2.0) {sea water};
    \node at (2.4, 5.8) [right] {thermometer};
    \draw[thin, -stealth] (2.4, 5.8) -- (2.05, 5.8);

    \node at (6.5, 3.8) {X};
    \draw[thin, -stealth] (6.5, 3.6) -- (6.0, 2.6);

    \node at (3.6, 4.3) [above left] {water out};
    \draw[thin, -stealth] (3.6, 4.3) -- (4.4, 3.3);

    \node at (8.0, 0.5) [right] {water in};
    \draw[thin, -stealth] (8.0, 0.5) -- (7.5, 1.3);

    \node at (10.2, -1.2) [right] {pure water};
    \draw[thin, -stealth] (10.2, -1.2) -- (9.5, -1.2);

    \node at (2, 0.5) {heat};
    \draw[thin, -stealth] (2, 0.7) -- (2, 1.0);

    % Caption
    \node at (5, -2.3) {Fig. 4.1};

\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=0.9, every node/.style={font=\sffamily}]
    % Bunsen burner and flame
    \draw[thick] (1.5,0) rectangle (2.5,0.4);
    \draw[thick] (1.8,0.4) -- (1.8,1.2);
    \draw[thick] (2.2,0.4) -- (2.2,1.2);
    \draw[thick, fill=gray!30] (2,1.2) ellipse (0.4 and 0.1);
    % Flame
    \draw[thick, orange, fill=orange!30] (2,1.3) .. controls (1.6,2.2) and (1.9,2.5) .. (2,3.0) .. controls (2.1,2.5) and (2.4,2.2) .. (2,1.3);
    \draw[thick, blue, fill=blue!20] (2,1.3) .. controls (1.8,1.8) and (1.9,2.0) .. (2,2.3) .. controls (2.1,2.0) and (2.2,1.8) .. (2,1.3);

    % Tripod and wire gauze
    \draw[thick] (0.5,2.6) -- (3.5,2.6); % wire gauze
    \draw[thick] (0.5,2.6) -- (0.2,0);   % left leg
    \draw[thick] (3.5,2.6) -- (3.8,0);   % right leg

    % Round bottomed flask
    \draw[thick] (2,2.7) circle (1.5);

    % Sea water liquid inside flask
    \begin{scope}
        \clip (2,2.7) circle (1.48);
        \fill[gray!20] (0,0) rectangle (4,2.3);
        \foreach \x in {1.2, 1.6, 2.0, 2.4, 2.8}
            \foreach \y in {1.5, 1.8, 2.1}
                \node[circle,fill,inner sep=0.7pt,gray!60] at (\x+\y*0.1-0.2, \y) {};
    \end{scope}
    \draw[thick] (2,2.7) circle (1.5);

    % Flask neck and side arm junction
    \draw[thick] (1.6,4.2) -- (1.6,4.6);
    \draw[thick] (2.4,4.2) -- (2.4,4.6);

    % Side arm leading from neck to condenser
    \draw[thick] (2.4,4.2) -- (4.2, 3.4);
    \draw[thick] (2.4,3.9) -- (3.9, 3.2);

    % Cork / Stopper in neck
    \fill[white] (1.6,4.2) rectangle (2.4,4.6);
    \draw[thick, fill=gray!40] (1.6,4.2) rectangle (2.4,4.6);
    \draw[thick] (1.6,4.6) -- (2.4,4.6);
    \draw[thick] (1.6,4.2) -- (2.4,4.2);

    % Thermometer
    \draw[thick] (2,5.8) -- (2,3.9);
    \draw[thick] (2,5.8) circle (0.08);
    \draw[thick, fill=red] (2,4.2) circle (0.08); % bulb level with side arm
    \draw[thick] (1.9,4.4) -- (2.1,4.4);
    \draw[thick] (1.9,4.8) -- (2.1,4.8);
    \draw[thick] (1.9,5.2) -- (2.1,5.2);
    \draw[thick] (1.9,5.6) -- (2.1,5.6);

    % --- LIEBIG CONDENSER (X) ---
    % Rotated coordinate system along condenser axis (-25 degrees)
    \begin{scope}[shift={(4.0, 3.3)}, rotate=-25]
        % Inner glass tube passing straight through
        \draw[thick, fill=white] (0, 0.1) -- (5.5, 0.1) -- (5.5, -0.1) -- (0, -0.1) -- cycle;

        % Outer water jacket
        \draw[thick, fill=white] (0.8, 0.4) rectangle (4.7, -0.4);

        % Water In (lower end, right side of jacket)
        \draw[thick] (4.2, -0.4) -- (4.2, -0.8);
        \draw[thick] (4.4, -0.4) -- (4.4, -0.8);
        \fill[white] (4.2,-0.45) rectangle (4.4,-0.35);

        % Water Out (upper end, left side of jacket)
        \draw[thick] (1.3, 0.4) -- (1.3, 0.8);
        \draw[thick] (1.5, 0.4) -- (1.5, 0.8);
        \fill[white] (1.3,0.35) rectangle (1.5,0.45);
    \end{scope}

    % Outlet adapter / drop leading to conical flask
    \draw[thick] (9.0, 0.8) -- (9.4, 0.2);
    \draw[thick] (8.7, 0.6) -- (9.1, 0.0);

    % Conical flask
    \draw[thick] (9.0,-1.5) -- (10.0,-1.5) -- (9.6,-0.5) -- (9.3,-0.5) -- cycle;
    \draw[thick] (9.3,-0.5) -- (9.3,0.0) -- (9.6,0.0) -- (9.6,-0.5);
    \fill[white] (9.3,-0.5) rectangle (9.6,0.0);
    \draw[thick] (9.3,-0.5) -- (9.3,0.0);
    \draw[thick] (9.6,-0.5) -- (9.6,0.0);

    % Pure water liquid in conical flask
    \fill[gray!20] (9.15,-1.45) rectangle (9.8,-1.0);
    \draw[thick] (9.0,-1.5) -- (10.0,-1.5) -- (9.6,-0.5) -- (9.3,-0.5) -- cycle;
    % Drop inside neck
    \draw[thick, fill=blue!30] (9.45,-0.25) circle (0.05);

    % --- LABELS & LEADERS ---
    \node at (2, 2.0) {sea water};

    \node at (-0.3, 5.8) [right] {thermometer};
    \draw[thin, -stealth] (-0.3, 5.8) -- (1.95, 5.8);

    \node at (5.3, 2.6) {X};
    \draw[thin, -stealth] (5.1, 2.4) -- (4.8, 2.0);

    \node at (2.2, 4.2) [above left] {water out};
    \draw[thin, -stealth] (2.2, 4.3) -- (4.8, 2.9);

    \node at (7.0, -0.4) [right] {water in};
    \draw[thin, -stealth] (7.0, -0.4) -- (7.6, 0.4);

    \node at (10.2, -1.2) [right] {pure water};
    \draw[thin, -stealth] (10.2, -1.2) -- (9.7, -1.2);

    \node at (2, 0.2) {heat};
    \draw[thin, -stealth] (2, 0.35) -- (2, 0.8);

    % Caption
    \node at (5, -2.3) {Fig. 4.1};

\end{tikzpicture}
